// Generates the mobile app's barangay pin-suggestion lookup from the backend CSV.
// Run FROM THE MONOREPO ROOT (where farmgate-backend/ and client/ sit together):
//   node farmgate-backend/scripts/gen-barangay-pins.js
// Output: client/mobile/constants/barangayPins.ts (569 barangays).
// Do NOT edit the output by hand — rerun this generator instead.
"use strict";
const fs = require("fs");
const path = require("path");

// Monorepo root: two levels up from farmgate-backend/scripts/.
const ROOT = path.join(__dirname, "..", "..");
const CSV = path.join(ROOT, "farmgate-backend", "data", "bulacan_barangays.csv");
const OUT = path.join(ROOT, "client", "mobile", "constants", "barangayPins.ts");

const norm = (s) => String(s || "").trim().replace(/\s+/g, " ").toLowerCase();

if (!fs.existsSync(CSV)) {
  console.error("CSV not found: " + CSV);
  console.error("Run this from the monorepo root (needs farmgate-backend/ + client/ side by side).");
  process.exit(1);
}
if (!fs.existsSync(path.dirname(OUT))) {
  console.error("Output dir not found: " + path.dirname(OUT));
  process.exit(1);
}

const lines = fs.readFileSync(CSV, "utf8").trim().split(/\r?\n/);
const header = lines.shift();
if (header.trim() !== "city,barangay,lat,lng") {
  console.error("BAD HEADER: " + header);
  process.exit(1);
}
const entries = [];
const seen = new Set();
for (const line of lines) {
  const parts = line.split(",");
  if (parts.length < 4) { console.error("BAD LINE: " + line); process.exit(1); }
  const city = parts[0].trim();
  const brgy = parts[1].trim();
  const lat = Number(parts[2]);
  const lng = Number(parts[3]);
  if (!city || !brgy || !Number.isFinite(lat) || !Number.isFinite(lng)) {
    console.error("BAD VALUES: " + line);
    process.exit(1);
  }
  const key = norm(city) + "|" + norm(brgy);
  if (seen.has(key)) { console.error("DUP KEY: " + key); process.exit(1); }
  seen.add(key);
  entries.push({ key, lat, lng });
}
entries.sort((a, b) => (a.key < b.key ? -1 : 1));

let out = "// AUTO-GENERATED by farmgate-backend/scripts/gen-barangay-pins.js ";
out += "from farmgate-backend/data/bulacan_barangays.csv (" + entries.length + " barangays).\n";
out += "// Do not edit by hand — rerun the generator instead.\n";
out += "// Barangay-center pins for AUTO-SUGGESTION ONLY (map starting point when a\n";
out += "// barangay is picked). Delivery is ALWAYS priced from the map pin saved\n";
out += "// on the profile/address via OSRM — never from text. The suggestion is\n";
out += "// saveable as-is; the user may drag to adjust (pinAuto) but is not required to.\n";
out += "export type BarangayPin = { lat: number; lng: number };\n\n";
out += "const BARANGAY_PINS: Record<string, BarangayPin> = {\n";
for (const e of entries) {
  out += "  " + JSON.stringify(e.key) + ": { lat: " + e.lat + ", lng: " + e.lng + " },\n";
}
out += "};\n\n";
out += "const normKey = (s: string): string =>\n";
out += '  String(s || "").trim().replace(/\\s+/g, " ").toLowerCase();\n\n';
out += "export const barangayPinFor = (city: string, barangay: string): BarangayPin | null => {\n";
out += '  const hit = BARANGAY_PINS[normKey(city) + "|" + normKey(barangay)];\n';
out += "  return hit ? { lat: hit.lat, lng: hit.lng } : null;\n";
out += "};\n";
fs.writeFileSync(OUT, out);
console.log("WROTE " + entries.length + " pins -> " + OUT);
